// Manual entries carry no title/company/description yet — extraction is
// the responsibility of the evaluate-job sub-workflow (Playwright/WebFetch
// against the pasted URL), same as career-ops' pipeline.md URL inbox.
return [{
  json: {
    company: '',
    title: '',
    url: $input.item.json.url,
    location: '',
    comp_text: '',
    posted_at: null,
    description: '',
    source_platform: 'manual_inbox',
    manual_inbox_id: $input.item.json.id,
    note: $input.item.json.note || '',
  }
}];
